  'https://bistrava.com/izdelki/samocistilni-filter-za-vodo', '{"sourceUrl": "https://ggv.si/trgovina/cista-voda-za-vas-dom/", "officialSourceUrl": "https://ggv.si/izdelek/filter-za-vodo-gevor/", "sourceRow": 45, "draftOnly": true, "draftImages": [{"url": "/products/samocistilni-filter-za-vodo/official-1.webp", "altSl": "Gevor – samočistilni filter za vodo – uradni prikaz izdelka 1", "width": 1200, "height": 1200, "kind": "official", "sourceName": "GGV d.o.o.", "sourceUrl": "https://ggv.si/izdelek/filter-za-vodo-gevor/"}, {"url": "/products/samocistilni-filter-za-vodo/official-2.jpg", "altSl": "Gevor – samočistilni filter za vodo – uradni prikaz izdelka 2", "width": 1200, "height": 1200, "kind": "official", "sourceName": "GGV d.o.o.", "sourceUrl": "https://ggv.si/izdelek/filter-za-vodo-gevor/"}, {"url": "/products/samocistilni-filter-za-vodo/bistrava-panel-1.svg", "altSl": "Gevor – samočistilni filter za vodo – ključne lastnosti", "width": 1200, "height": 1200, "kind": "information", "sourceName": "Bistrava", "sourceUrl": "/izdelki/samocistilni-filter-za-vodo"}, {"url": "/products/samocistilni-filter-za-vodo/bistrava-panel-2.svg", "altSl": "Gevor – samočistilni filter za vodo – tehnični podatki", "width": 1200, "height": 1200, "kind": "information", "sourceName": "Bistrava", "sourceUrl": "/izdelki/samocistilni-filter-za-vodo"}]}'::jsonb
