) values (
  'BIS-054', 'Polifosfatni filter za pralni ali pomivalni stroj', 'Polifosfatni filter za pralni ali pomivalni stroj',
  'filter-za-pralni-stroj', 'Več blagovnih znamk', 'Kompaktni polifosfatni filter s priključkom 3/4″ in 160 g kristalov je namenjen zaščiti posameznega pralnega ali pomivalnega stroja.', 'Kompaktni polifosfatni filter s priključkom 3/4″ in 160 g kristalov je namenjen zaščiti posameznega pralnega ali pomivalnega stroja.',
  'Polifosfatni filter se namesti na standardni dovod vode pred pralnim ali pomivalnim strojem. Natrijev polifosfat deluje na karbonate v vodi in pomaga omejevati njihovo odlaganje na ceveh ter grelnih elementih posamezne naprave. To je ciljna zaščita porabnika in ni enakovredna centralnemu mehčanju vode z ionsko izmenjavo.

Ohišje je visoko 130 mm, vsebuje 160 g polifosfatnih kristalov ter uporablja 3/4-palčni vhodni in izhodni navoj. Dobavitelj navaja največji tlak 7 bar in temperaturo 35 °C. Pred uporabo je treba preveriti kakovost vode, navodila proizvajalca aparata ter primernost za predvideni dovod.', 'Polifosfatni filter se namesti na standardni dovod vode pred pralnim ali pomivalnim strojem. Natrijev polifosfat deluje na karbonate v vodi in pomaga omejevati njihovo odlaganje na ceveh ter grelnih elementih posamezne naprave. To je ciljna zaščita porabnika in ni enakovredna centralnemu mehčanju vode z ionsko izmenjavo.

Ohišje je visoko 130 mm, vsebuje 160 g polifosfatnih kristalov ter uporablja 3/4-palčni vhodni in izhodni navoj. Dobavitelj navaja največji tlak 7 bar in temperaturo 35 °C. Pred uporabo je treba preveriti kakovost vode, navodila proizvajalca aparata ter primernost za predvideni dovod.', 'draft', 'Doziranje natrijevega polifosfata za ciljno zaščito',
  '["Priključek 3/4″", "160 g polifosfatnih kristalov", "Za posamezen gospodinjski aparat", "Največji tlak 7 bar"]'::jsonb, '[{"labelSl": "Priključek", "valueSl": "3/4″ vhod in izhod"}, {"labelSl": "Polnilo", "valueSl": "160 g natrijevega polifosfata, kristali 6/10"}, {"labelSl": "Material ohišja", "valueSl": "Ojačani polipropilen in SAN"}, {"labelSl": "Višina", "valueSl": "130 mm"}, {"labelSl": "Največji tlak", "valueSl": "7 bar"}, {"labelSl": "Največja temperatura", "valueSl": "35 °C"}]'::jsonb, null, 1830,
  null, true, 'GGV d.o.o.',
  'https://ggv.si/izdelek/filter-za-pralni-stroj-s-fosfati/', '2026-08-24', 'Javno objavljena maloprodajna cena pri navedenem viru; ne predstavlja nabavne ali prodajne cene Bistrava.',
  22.00, 'EUR', 'installation_required', 'unverified', 5,
