  'https://bistrava.com/izdelki/clack-mehcalna-naprava', '{"sourceUrl": "https://www.ceneje.si/L3/1755/gradbenistvo/vodovod-odtoki/mehcanje-vode", "officialSourceUrl": "https://filtri-za-vodo.si/trgovina/filtri-za-celo-hiso/vodni-kamen-filtri-za-celo-hiso/ionske-mehcalne-naprave-vodni-kamen-filtri-za-celo-hiso/ionska-mehcalna-naprava-tehnofan-antraciteazure-250-clack-compact/", "sourceRow": 87, "draftOnly": true, "draftImages": [{"url": "/products/clack-mehcalna-naprava/official-1.png", "altSl": "AntraciteAzure 250 Clack Compact – mehčalna naprava – uradni prikaz izdelka 1", "width": 1200, "height": 1200, "kind": "official", "sourceName": "Tehnofan d.o.o.", "sourceUrl": "https://filtri-za-vodo.si/trgovina/filtri-za-celo-hiso/vodni-kamen-filtri-za-celo-hiso/ionske-mehcalne-naprave-vodni-kamen-filtri-za-celo-hiso/ionska-mehcalna-naprava-tehnofan-antraciteazure-250-clack-compact/"}, {"url": "/products/clack-mehcalna-naprava/bistrava-panel-1.svg", "altSl": "AntraciteAzure 250 Clack Compact – mehčalna naprava – ključne lastnosti", "width": 1200, "height": 1200, "kind": "information", "sourceName": "Bistrava", "sourceUrl": "/izdelki/clack-mehcalna-naprava"}, {"url": "/products/clack-mehcalna-naprava/bistrava-panel-2.svg", "altSl": "AntraciteAzure 250 Clack Compact – mehčalna naprava – tehnični podatki", "width": 1200, "height": 1200, "kind": "information", "sourceName": "Bistrava", "sourceUrl": "/izdelki/clack-mehcalna-naprava"}, {"url": "/products/clack-mehcalna-naprava/bistrava-panel-3.svg", "altSl": "AntraciteAzure 250 Clack Compact – mehčalna naprava – uporaba in načrtovanje", "width": 1200, "height": 1200, "kind": "information", "sourceName": "Bistrava", "sourceUrl": "/izdelki/clack-mehcalna-naprava"}]}'::jsonb
