  seo_title, seo_description, canonical_url, merchant_data
) values (
  'BIS-084', 'Dodatni senzor Wireless Water Guard za izlitje vode', 'Dodatni senzor Wireless Water Guard za izlitje vode',
  'senzor-za-izlitje-vode', 'WWG', 'Dodatni brezžični senzor razširi sistem Wireless Water Guard in zazna vodo na izbranem tveganem mestu; sistem podpira do pet senzorjev.', 'Dodatni brezžični senzor razširi sistem Wireless Water Guard in zazna vodo na izbranem tveganem mestu; sistem podpira do pet senzorjev.',
  'Dodatni senzor Wireless Water Guard se namesti na mesto, kjer je možen izliv vode, na primer ob pralnem ali pomivalnem stroju, grelniku, filtru ali razdelilniku. Ko tipalo zazna vodo, brezžično obvesti združljivo krmilno enoto, ki prek električnega ventila zapre glavni dovod.

Senzor je razširitev sistema WWG in samostojno ne more zapreti vode. Dobavitelj navaja možnost povezave do petih senzorjev v en sistem. Pred namestitvijo preverite radijski doseg, napajanje oziroma baterijo, združljivost z obstoječo enoto in izberite mesto, kjer bo tipalo hitro prišlo v stik z izteklo vodo.', 'Dodatni senzor Wireless Water Guard se namesti na mesto, kjer je možen izliv vode, na primer ob pralnem ali pomivalnem stroju, grelniku, filtru ali razdelilniku. Ko tipalo zazna vodo, brezžično obvesti združljivo krmilno enoto, ki prek električnega ventila zapre glavni dovod.

Senzor je razširitev sistema WWG in samostojno ne more zapreti vode. Dobavitelj navaja možnost povezave do petih senzorjev v en sistem. Pred namestitvijo preverite radijski doseg, napajanje oziroma baterijo, združljivost z obstoječo enoto in izberite mesto, kjer bo tipalo hitro prišlo v stik z izteklo vodo.', 'draft', 'Brezžično zaznavanje prisotnosti vode',
  '["Razširitev sistema WWG", "Brezžično zaznavanje vode", "Postavitev ob tvegan porabnik", "Do 5 senzorjev v sistemu"]'::jsonb, '[{"labelSl": "Tip", "valueSl": "Brezžični senzor prisotnosti vode"}, {"labelSl": "Združljivost", "valueSl": "Wireless Water Guard"}, {"labelSl": "Največ senzorjev v sistemu", "valueSl": "5"}, {"labelSl": "Samostojno delovanje", "valueSl": "Ne; potrebna je združljiva krmilna enota in ventil"}, {"labelSl": "Priporočena mesta", "valueSl": "Pralni stroj, pomivalni stroj, grelnik, filter ali razdelilnik"}]'::jsonb, null, 4898,
